        case WASM_TYPE_NOFUNC:
            r.of.funcref = UINT32_MAX;
            break;
        case WASM_TYPE_EXTERNREF:
        case WASM_TYPE_NOEXTERN:
        case WASM_TYPE_EXNREF:
        case WASM_TYPE_NOEXN:
            r.of.externref = (uintptr_t)0;
            break;
