                break;
            case 0x39:
                truth = (a < b);
                break;
            case 0x3A:
                truth = (ua < ub);
                break;
            case 0x3B:
                truth = (a > b);
                break;
            case 0x3C:
                truth = (ua > ub);
                break;
            case 0x3D:
