    entry = wasm__wasi_fd_entry(rt, (uint32_t)args[2].of.i32);
    if (!entry || !wasm__wasi_entry_can_path(entry)) {
        wasm__wasi_set_errno(results, num_results, WASM__WASI_ERRNO_BADF);
        return WASM_OK;
    }
