#include <string.h>
#include <stdio.h>

/* Compiled modules have declared memories but no storage. */
static wasm_memory_t* wasm__instance_memory_at(const wasm_module_t* mod, uint32_t memory_index) {
    return mod && !mod->is_compiled ? wasm__memory_at(mod, memory_index) : NULL;
}

uint32_t wasm_memory_count(const wasm_module_t* mod) {
    return mod ? mod->num_memories : 0;
}

wasm_error_t wasm_memory_read(const wasm_module_t* mod, uint32_t memory_index,
                              uint64_t offset, void* dst, size_t len) {
    wasm_memory_t* memory;
    uint64_t mem_size;

    if (!mod || (len > 0 && !dst)) {
        if (mod && mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_MALFORMED, "%s", "invalid memory read arguments");
        return WASM_ERR_MALFORMED;
    }

    memory = wasm__instance_memory_at(mod, memory_index);
    if (!memory) {
        if (mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_MALFORMED,
                          "unknown memory %u", (unsigned)memory_index);
        return WASM_ERR_MALFORMED;
    }

    mem_size = wasm__memory_byte_size(memory);
    if (!wasm__range_in_bounds_u64(offset, (uint64_t)len, mem_size)) {
        if (mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_OUT_OF_BOUNDS,
                          "memory %u read out of bounds: offset=%llu len=%zu size=%llu",
                          (unsigned)memory_index, (unsigned long long)offset, len,
                          (unsigned long long)mem_size);
        return WASM_ERR_OUT_OF_BOUNDS;
    }

    if (len > 0) memcpy(dst, memory->data + offset, len);
    return WASM_OK;
}

wasm_error_t wasm_memory_write(wasm_module_t* mod, uint32_t memory_index,
                               uint64_t offset, const void* src, size_t len) {
    wasm_memory_t* memory;
    uint64_t mem_size;

    if (!mod || (len > 0 && !src)) {
        if (mod && mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_MALFORMED, "%s", "invalid memory write arguments");
        return WASM_ERR_MALFORMED;
    }

    memory = wasm__instance_memory_at(mod, memory_index);
    if (!memory) {
        if (mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_MALFORMED,
                          "unknown memory %u", (unsigned)memory_index);
        return WASM_ERR_MALFORMED;
    }

    mem_size = wasm__memory_byte_size(memory);
    if (!wasm__range_in_bounds_u64(offset, (uint64_t)len, mem_size)) {
        if (mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_OUT_OF_BOUNDS,
                          "memory %u write out of bounds: offset=%llu len=%zu size=%llu",
                          (unsigned)memory_index, (unsigned long long)offset, len,
                          (unsigned long long)mem_size);
        return WASM_ERR_OUT_OF_BOUNDS;
    }

    if (len > 0) memcpy(memory->data + offset, src, len);
    return WASM_OK;
}

wasm_error_t wasm_memory_get_string(const wasm_module_t* mod, uint32_t memory_index,
                                    uint64_t offset, char* dst, size_t max_len) {
    wasm_memory_t* memory;
    uint64_t mem_size;
    uint64_t available_u64;
    size_t max_copy;
    size_t actual_len = 0;
    const uint8_t* src;

    if (!mod || !dst || max_len == 0) {
        if (mod && mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_MALFORMED, "%s", "invalid string extraction arguments");
        return WASM_ERR_MALFORMED;
    }

    memory = wasm__instance_memory_at(mod, memory_index);
    if (!memory) {
        if (mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_MALFORMED,
                          "unknown memory %u", (unsigned)memory_index);
        return WASM_ERR_MALFORMED;
    }

    mem_size = wasm__memory_byte_size(memory);
    if (offset > mem_size) {
        if (mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_OUT_OF_BOUNDS,
                          "memory %u string offset out of bounds: offset=%llu size=%llu",
                          (unsigned)memory_index, (unsigned long long)offset,
                          (unsigned long long)mem_size);
        return WASM_ERR_OUT_OF_BOUNDS;
    }

    available_u64 = mem_size - offset;
    max_copy = max_len - 1u;
    if ((uint64_t)max_copy > available_u64) max_copy = (size_t)available_u64;

    src = memory->data ? memory->data + offset : NULL;
    if (src) {
        while (actual_len < max_copy && src[actual_len] != 0) actual_len++;
        if (actual_len > 0) memcpy(dst, src, actual_len);
    }

    dst[actual_len] = '\0';
    return WASM_OK;
}

uint8_t* wasm_memory_data(wasm_module_t* mod, uint32_t memory_index) {
    wasm_memory_t* memory = wasm__instance_memory_at(mod, memory_index);
    return memory ? memory->data : NULL;
}

uint64_t wasm_memory_size(const wasm_module_t* mod, uint32_t memory_index) {
    wasm_memory_t* memory = wasm__memory_at(mod, memory_index);
    return memory ? wasm__memory_byte_size(memory) : 0;
}

/* Shared memories grow in place within their reservation, so threads holding data pointers stay valid. */
static int64_t wasm__shared_memory_grow(wasm_memory_t* memory, uint64_t delta_pages) {
    uint64_t page_size = wasm__memory_page_size(memory);
    uint64_t old;
    uint64_t np;
    int64_t result = -1;

    wasm__platform_shared_grow_lock();
    old = memory->pages;
    np = old + delta_pages;
    if (delta_pages <= UINT64_MAX - old && np <= memory->max_pages && np <= memory->reserved_bytes / page_size &&
        wasm__platform_shared_commit(memory->data, np * page_size)) {
        memory->pages = np;
        wasm__atomic_store_size(&memory->shared_size, (size_t)(np * page_size));
        result = (int64_t)old;
    }
    wasm__platform_shared_grow_unlock();
    return result;
}

int64_t wasm_memory_grow(wasm_module_t* mod, uint32_t memory_index, uint64_t delta_pages) {
    wasm_memory_t* memory = wasm__instance_memory_at(mod, memory_index);
    uint64_t old, np;
    size_t old_size;
    size_t new_size;
    uint8_t* nd;

    if (!memory) return -1;
    old = memory->pages;
    if (delta_pages > UINT64_MAX - old) return -1;
    np = old + delta_pages;
    if (mod->rt && mod->rt->max_memory_bytes != 0 && np > mod->rt->max_memory_bytes / wasm__memory_page_size(memory))
        return -1;
    if (mod->rt && mod->rt->max_total_memory_bytes != 0) {
        uint64_t total = wasm__runtime_memory_bytes(mod->rt);
        uint64_t limit = mod->rt->max_total_memory_bytes;

        if (total > limit || delta_pages > (limit - total) / wasm__memory_page_size(memory)) return -1;
    }
    if (memory->is_shared) return wasm__shared_memory_grow(memory, delta_pages);
    if (np > memory->max_pages) return -1;
    memory->pages = old;
    if (!wasm__memory_byte_size_fits_host(memory, &old_size)) return -1;
    memory->pages = np;
    if (!wasm__memory_byte_size_fits_host(memory, &new_size)) {
        memory->pages = old;
        return -1;
    }
    memory->pages = old;
    if (new_size == old_size) return (int64_t)old;
    nd = (uint8_t*)wasm__resize_sized(&memory->allocator, memory->data, old_size, new_size, WASM__BLOCK_ALIGN);
    if (!nd) return -1;
    if (new_size > old_size) memset(nd + old_size, 0, new_size - old_size);
    memory->data = nd;
    memory->pages = np;
    return (int64_t)old;
}

wasm_memory_t* wasm_module_memory(wasm_module_t* mod, uint32_t memory_index) {
    return wasm__memory_at(mod, memory_index);
}

uint32_t wasm_table_count(const wasm_module_t* mod) {
    return mod ? mod->num_tables : 0;
}

wasm_table_t* wasm_module_table(wasm_module_t* mod, uint32_t table_idx) {
    return wasm__table_at(mod, table_idx);
}

wasm_valtype_t wasm_table_type(const wasm_module_t* mod, uint32_t table_idx) {
    wasm_table_t* table = wasm__table_at(mod, table_idx);
    return table ? table->reftype : WASM_TYPE_VOID;
}

const wasm_reftype_t* wasm_table_reftype(const wasm_module_t* mod, uint32_t table_idx) {
    wasm_table_t* table = wasm__table_at(mod, table_idx);
    return table ? &table->reftype_info : NULL;
}

static wasm_table_t* wasm__api_table(const wasm_module_t* mod, uint32_t table_idx) {
    wasm_table_t* table = (mod && !mod->is_compiled) ? wasm__table_at(mod, table_idx) : NULL;

    if (!table && mod && mod->rt) WASM__SET_ERR(mod->rt, WASM_ERR_MALFORMED, "table %u not found", (unsigned)table_idx);
    return table;
}

uint64_t wasm_table_size(const wasm_module_t* mod, uint32_t table_idx) {
    wasm_table_t* table = (mod && !mod->is_compiled) ? wasm__table_at(mod, table_idx) : NULL;

    return table ? table->size : 0;
}

wasm_error_t wasm_table_get(const wasm_module_t* mod, uint32_t table_idx, uint64_t index, wasm_value_t* out_val) {
    wasm_table_t* table = wasm__api_table(mod, table_idx);

    if (!table || !out_val) return WASM_ERR_MALFORMED;
    if (index >= table->size) {
        WASM__SET_ERR(mod->rt, WASM_ERR_OUT_OF_BOUNDS, "table index %llu out of bounds", (unsigned long long)index);
        return WASM_ERR_OUT_OF_BOUNDS;
    }
    *out_val = table->elems[index];
    return WASM_OK;
}

wasm_error_t wasm_table_set(wasm_module_t* mod, uint32_t table_idx, uint64_t index, wasm_value_t val) {
    wasm_table_t* table = wasm__api_table(mod, table_idx);

    if (!table) return WASM_ERR_MALFORMED;
    if (index >= table->size) {
        WASM__SET_ERR(mod->rt, WASM_ERR_OUT_OF_BOUNDS, "table index %llu out of bounds", (unsigned long long)index);
        return WASM_ERR_OUT_OF_BOUNDS;
    }
    if (!wasm__runtime_value_matches_type(mod, &val, table->reftype, &table->reftype_info)) {
        WASM__SET_ERR(mod->rt, WASM_ERR_TYPE_MISMATCH, "%s", "value does not match the table's element type");
        return WASM_ERR_TYPE_MISMATCH;
    }
    table->elems[index] = val;
    return WASM_OK;
}

int64_t wasm_table_grow(wasm_module_t* mod, uint32_t table_idx, uint64_t delta, wasm_value_t init) {
    wasm_table_t* table = wasm__api_table(mod, table_idx);
    uint64_t old_size;

    if (!table || !wasm__runtime_value_matches_type(mod, &init, table->reftype, &table->reftype_info)) return -1;
    old_size = wasm__table_grow(mod->rt, table, delta, init);
    return old_size == UINT64_MAX ? -1 : (int64_t)old_size;
}

uint32_t wasm_global_count(const wasm_module_t* mod) {
    return mod ? mod->num_globals : 0;
}

wasm_valtype_t wasm_global_type(const wasm_module_t* mod, uint32_t global_idx) {
    if (!mod || global_idx >= mod->num_globals) return WASM_TYPE_VOID;
    return mod->globals[global_idx].type;
}

const wasm_reftype_t* wasm_global_reftype(const wasm_module_t* mod, uint32_t global_idx) {
    if (!mod || global_idx >= mod->num_globals) return NULL;
    return &mod->globals[global_idx].ref_type;
}

int wasm_global_is_mutable(const wasm_module_t* mod, uint32_t global_idx) {
    if (!mod || global_idx >= mod->num_globals) return 0;
    return mod->globals[global_idx].is_mutable;
}

wasm_value_t* wasm_module_global(wasm_module_t* mod, uint32_t global_idx) {
    wasm_global_t* global;

    if (!mod || mod->is_compiled || global_idx >= mod->num_globals) return NULL;
    global = &mod->globals[global_idx];
    return global->is_import ? global->import_value : &global->value;
}

static wasm_global_t* wasm__api_global(const wasm_module_t* mod, uint32_t global_idx) {
    if (!mod || mod->is_compiled || global_idx >= mod->num_globals) {
        if (mod && mod->rt) WASM__SET_ERR(mod->rt, WASM_ERR_MALFORMED, "global %u not found", (unsigned)global_idx);
        return NULL;
    }
    return &mod->globals[global_idx];
}

wasm_error_t wasm_global_get_index(const wasm_module_t* mod, uint32_t global_idx, wasm_value_t* out_val) {
    wasm_global_t* global = wasm__api_global(mod, global_idx);

    if (!global || !out_val) return WASM_ERR_MALFORMED;
    *out_val = wasm__global_get_value(global);
    return WASM_OK;
}

wasm_error_t wasm_global_set_index(wasm_module_t* mod, uint32_t global_idx, wasm_value_t val) {
    wasm_global_t* global = wasm__api_global(mod, global_idx);

    if (!global) return WASM_ERR_MALFORMED;
    if (!global->is_mutable) {
        WASM__SET_ERR(mod->rt, WASM_ERR_TYPE_MISMATCH, "global %u is immutable", (unsigned)global_idx);
        return WASM_ERR_TYPE_MISMATCH;
    }
    if (!wasm__runtime_value_matches_type(mod, &val, global->type, &global->ref_type)) {
        WASM__SET_ERR(mod->rt, WASM_ERR_TYPE_MISMATCH, "global %u type mismatch", (unsigned)global_idx);
        return WASM_ERR_TYPE_MISMATCH;
    }
    wasm__global_set_value(global, val);
    return WASM_OK;
}

wasm_error_t wasm_global_get(const wasm_module_t* mod, const char* name, wasm_value_t* out_val) {
    wasm_global_t* global;
    wasm_error_t err;

    if (!mod || !name || !out_val) {
        if (mod && mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_MALFORMED, "%s", "invalid global get arguments");
        return WASM_ERR_MALFORMED;
    }

    if (mod->is_compiled) {
        WASM__SET_ERR(mod->rt, WASM_ERR_MALFORMED, "%s", "module is compiled but not instantiated");
        return WASM_ERR_MALFORMED;
    }
    err = wasm__resolve_exported_global(mod, name, &global, NULL);
    if (err != WASM_OK) return err;

    *out_val = wasm__global_get_value(global);
    return WASM_OK;
}

wasm_error_t wasm_global_set(wasm_module_t* mod, const char* name, wasm_value_t val) {
    wasm_global_t* global;
    wasm_error_t err;

    if (!mod || !name) {
        if (mod && mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_MALFORMED, "%s", "invalid global set arguments");
        return WASM_ERR_MALFORMED;
    }

    if (mod->is_compiled) {
        WASM__SET_ERR(mod->rt, WASM_ERR_MALFORMED, "%s", "module is compiled but not instantiated");
        return WASM_ERR_MALFORMED;
    }
    err = wasm__resolve_exported_global(mod, name, &global, NULL);
    if (err != WASM_OK) return err;

    if (!global->is_mutable) {
        if (mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_TYPE_MISMATCH,
                          "global '%s' is immutable", name);
        return WASM_ERR_TYPE_MISMATCH;
    }
    if (!wasm__runtime_value_matches_type(mod, &val, global->type, &global->ref_type)) {
        if (mod->rt)
            WASM__SET_ERR(mod->rt, WASM_ERR_TYPE_MISMATCH,
                          "global '%s' type mismatch", name);
        return WASM_ERR_TYPE_MISMATCH;
    }

    wasm__global_set_value(global, val);
    return WASM_OK;
}

